import { Button } from '@gouvfr-lasuite/cunningham-react';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Box, Icon, Text } from '@/components';
import type { PresentationCardData } from '@/features/chat/utils/presentationCard';

/**
 * A deck generated by the Presenton sidecar.
 *
 * The editor opens inline (iframe), not in a new tab: the sidecar runs
 * single-user on the same site in the POC, so its session flows into the
 * frame. See docs/presenton-sidecar.md for the auth posture.
 */
export const PresentationCard = ({
  presentation,
}: {
  presentation: PresentationCardData;
}) => {
  const { t } = useTranslation();
  const [editorOpen, setEditorOpen] = useState(false);

  return (
    <Box
      $direction="column"
      $gap="8px"
      $padding={{ all: '12px' }}
      $css="border: 1px solid var(--c--globals--colors--border-default); border-radius: 8px; max-width: 750px;"
    >
      <Box $direction="row" $align="center" $gap="8px">
        <Icon iconName="slideshow" $theme="primary" />
        <Box $direction="column" $flex={1} $css="min-width: 0;">
          <Text
            $weight="600"
            $size="md"
            $css="overflow: hidden; text-overflow: ellipsis; white-space: nowrap;"
          >
            {presentation.title}
          </Text>
          <Text $theme="neutral" $variation="secondary" $size="sm">
            {t('{{count}} slides', { count: presentation.slideCount })}
          </Text>
        </Box>
      </Box>

      <Box $direction="row" $gap="8px" $wrap="wrap">
        <Button
          size="small"
          color="primary"
          variant={editorOpen ? 'secondary' : 'primary'}
          aria-expanded={editorOpen}
          onClick={() => setEditorOpen((open) => !open)}
          icon={
            <Icon
              iconName={editorOpen ? 'expand_less' : 'edit'}
              $theme="inherit"
              $size="sm"
            />
          }
        >
          {editorOpen ? t('Close editor') : t('Edit slides')}
        </Button>
        {presentation.downloadUrl && (
          <Button
            size="small"
            color="neutral"
            variant="secondary"
            as="a"
            href={presentation.downloadUrl}
            download
            icon={<Icon iconName="download" $theme="inherit" $size="sm" />}
          >
            {t('Download PPTX')}
          </Button>
        )}
      </Box>

      {editorOpen && (
        <Box
          as="iframe"
          src={presentation.editorUrl}
          title={t('Slide editor: {{title}}', { title: presentation.title })}
          $css="width: 100%; height: 70vh; min-height: 420px; border: 1px solid var(--c--globals--colors--border-default); border-radius: 8px; background: white;"
        />
      )}
    </Box>
  );
};
